solutions.naive:
class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        stack = []
        for ch in s:
            if ch == "(":
                stack.append(ch)
            elif stack and stack[-1] == "(":
                stack.pop()
            else:
                stack.append(ch)
        return len(stack)

solutions.better:
class Solution:
    def minAddToMakeValid(self, s):
        opens = 0
        additions = 0
        for ch in s:
            if ch == "(":
                opens += 1
            elif opens:
                opens -= 1
            else:
                additions += 1
        return additions + opens

solutions.optimal:
class Solution:
    def minAddToMakeValid(self, s):
        balance = 0
        needed = 0
        for ch in s:
            balance += 1 if ch == "(" else -1
            if balance < 0:
                needed += 1
                balance = 0
        return needed + balance

